+      padding: 34px 34px 24px;
+      border-bottom: 1px solid var(--border);
+      background: linear-gradient(135deg, #ffffff 0%, #f7f8ff 100%);
+    }
+
+    .eyebrow {
+      margin: 0 0 10px;
+      color: var(--primary);
+      font-size: 0.78rem;
+      font-weight: 700;
+      letter-spacing: 0.12em;
+      text-transform: uppercase;
+    }
+
+    h1 {
+      margin: 0 0 10px;
+      font-size: clamp(1.9rem, 7vw, 2.55rem);
+      line-height: 1.05;
+      letter-spacing: -0.045em;
+    }
+
+    .intro {
+      margin: 0;
+      color: var(--muted);
+      font-size: 1rem;
+      line-height: 1.6;
+    }
+
+    form {
+      padding: 30px 34px 34px;
+    }
+
+    .form-field {
+      margin: 0 0 26px;
+      padding: 0;
+      border: 0;
+    }
+
+    legend {
+      margin-bottom: 16px;
+      color: var(--text);
+      font-size: 1.08rem;
+      font-weight: 750;
+    }
+
+    .options {
+      display: grid;
+      gap: 12px;
+    }
+
+    .radio-option {
+      position: relative;
+      display: flex;
+      align-items: center;
+      gap: 13px;
+      min-height: 58px;
+      padding: 15px 16px;
+      border: 1px solid var(--border);
+      border-radius: 16px;
+      background: #ffffff;
+      color: #273244;
+      cursor: pointer;
+      transition: border-color 180ms ease, box-shadow 180ms ease, transform 180ms ease, background 180ms ease;
+    }
+
+    .radio-option:hover {
+      transform: translateY(-1px);
+      border-color: #aab7ff;
+      box-shadow: 0 12px 24px rgba(79, 70, 229, 0.09);
+    }
+
+    .radio-option input {
+      width: 20px;
+      height: 20px;
+      margin: 0;
+      accent-color: var(--primary);
+    }
+
+    .radio-option:has(input:checked) {
+      border-color: var(--primary);
+      background: var(--primary-soft);
+      box-shadow: 0 12px 28px rgba(79, 70, 229, 0.16);
+    }
+
+    .option-text {
+      font-weight: 700;
+    }
+
+    .submit-button {
+      width: 100%;
+      border: 0;
+      border-radius: 16px;
+      padding: 15px 18px;
+      background: var(--primary);
+      color: #ffffff;
+      font: inherit;
+      font-weight: 800;
+      cursor: pointer;
+      box-shadow: 0 14px 30px rgba(79, 70, 229, 0.3);
+      transition: background 180ms ease, box-shadow 180ms ease, transform 180ms ease;
+    }
+
+    .submit-button:hover {
+      transform: translateY(-1px);
+      background: var(--primary-dark);
+      box-shadow: 0 18px 34px rgba(79, 70, 229, 0.34);
+    }
+
+    .submit-button:focus-visible,
+    .radio-option input:focus-visible {
+      outline: 3px solid rgba(79, 70, 229, 0.28);
+      outline-offset: 3px;
+    }
+
+    .status-message {
+      min-height: 24px;
+      margin: 16px 0 0;
+      color: var(--primary-dark);
+      font-weight: 700;
+      text-align: center;
+    }
+
+    @media (max-width: 520px) {
+      .card-header,
+      form {
+        padding-right: 24px;
+        padding-left: 24px;
+      }
+    }
+  </style>
+</head>
+<body>
+  <main>
+    <section class="preference-card" aria-labelledby="page-title">
+      <div class="card-header">
+        <p class="eyebrow">Preferences</p>
+        <h1 id="page-title">Stay in the loop</h1>
+        <p class="intro">Choose the channel that works best for timely product updates and account alerts.</p>
+      </div>
+
+      <form id="notification-form">
+        <fieldset class="form-field">
+          <legend>How do you prefer to receive notifications?</legend>
+          <div class="options">
+            <label class="radio-option">
+              <input type="radio" name="notification_preference" value="Email" required>
+              <span class="option-text">Email</span>
+            </label>
+
+            <label class="radio-option">
+              <input type="radio" name="notification_preference" value="SMS">
+              <span class="option-text">SMS</span>
+            </label>
+
+            <label class="radio-option">
+              <input type="radio" name="notification_preference" value="Push Notifications">
+              <span class="option-text">Push Notifications</span>
+            </label>
+          </div>
+        </fieldset>
+
+        <button class="submit-button" type="submit">Save preference</button>
+        <p class="status-message" id="status-message" aria-live="polite"></p>
+      </form>
+    </section>
+  </main>
+
+  <script>
+    const form = document.querySelector("#notification-form");
+    const statusMessage = document.querySelector("#status-message");
+
+    form.addEventListener("submit", (event) => {
+      event.preventDefault();
+
+      const selection = new FormData(form).get("notification_preference");
+      statusMessage.textContent = `Preference saved: ${selection}`;
+    });
+  </script>
+</body>
+</html>
*** End Patch
